#!/bin/bash
# gen-libs.sh - (re)generate the MSBuild projects for the external libraries that
# LAV Filters' ffmpeg links against: bzip2, speex, opencore-amr, libxml2, dav1d.
#
# Maintainer-time only (Git for Windows' bash is enough). Rerun after bumping one
# of the library submodules; the hand-maintained parts are the source lists below,
# taken from each library's own build system (meson.build / Makefile.am /
# Makefile.msvc), and the generated config headers written at the end.
set -e
M=$(cd "$(dirname "$0")/.." && pwd)     # .../LAVFilters/msvc
L="$M/libs"

# emit <dir> <name> <libname> <includes(;)> <defines(;)> <extra-cl-options> <items-file>
emit() {
  local dir=$1 name=$2 lib=$3 inc=$4 defs=$5 opts=$6 items=$7
  mkdir -p "$L/$dir"
  cat > "$L/$dir/$name.vcxproj" <<XML
<?xml version="1.0" encoding="utf-8"?>
<!-- generated by msvc/regen/gen-libs.sh - edit the source lists there, not here -->
<Project DefaultTargets="Build" ToolsVersion="17.0" xmlns="http://schemas.microsoft.com/developer/msbuild/2003">
  <ItemGroup Label="ProjectConfigurations">
    <ProjectConfiguration Include="Debug|Win32"><Configuration>Debug</Configuration><Platform>Win32</Platform></ProjectConfiguration>
    <ProjectConfiguration Include="Debug|x64"><Configuration>Debug</Configuration><Platform>x64</Platform></ProjectConfiguration>
    <ProjectConfiguration Include="Release|Win32"><Configuration>Release</Configuration><Platform>Win32</Platform></ProjectConfiguration>
    <ProjectConfiguration Include="Release|x64"><Configuration>Release</Configuration><Platform>x64</Platform></ProjectConfiguration>
  </ItemGroup>
  <PropertyGroup Label="Globals">
    <ProjectName>$name</ProjectName>
    <RootNamespace>$name</RootNamespace>
  </PropertyGroup>
  <Import Project="\$(VCTargetsPath)\Microsoft.Cpp.Default.props" />
  <PropertyGroup Label="Configuration">
    <ConfigurationType>StaticLibrary</ConfigurationType>
  </PropertyGroup>
  <Import Project="\$(MSBuildThisFileDirectory)..\..\common.props" />
  <Import Project="\$(VCTargetsPath)\Microsoft.Cpp.props" />
  <PropertyGroup>
    <TargetName>$lib</TargetName>
  </PropertyGroup>
  <ItemDefinitionGroup>
    <ClCompile>
      <AdditionalIncludeDirectories>$inc;%(AdditionalIncludeDirectories)</AdditionalIncludeDirectories>
      <PreprocessorDefinitions>$defs;%(PreprocessorDefinitions)</PreprocessorDefinitions>
      <AdditionalOptions>$opts %(AdditionalOptions)</AdditionalOptions>
    </ClCompile>
  </ItemDefinitionGroup>
  <ItemGroup>
$(cat "$items")
  </ItemGroup>
  <Import Project="\$(VCTargetsPath)\Microsoft.Cpp.targets" />
</Project>
XML
  echo "wrote libs/$dir/$name.vcxproj ($(grep -c '<ClCompile Include\|<CustomBuild Include' "$L/$dir/$name.vcxproj") items)"
}
w() { echo "$1" | tr '/' '\\'; }
# object names are derived from the relative path so that same-named files in
# different directories (dav1d: src/cpu.c vs src/x86/cpu.c) cannot overwrite each other
cl_item()    { local ob; ob=$(echo "${1%.*}" | sed 's|[/.]|_|g'); echo "    <ClCompile Include=\"$(w "$1")\"><ObjectFileName>\$(IntDir)$ob.obj</ObjectFileName></ClCompile>"; }
cl_item_bd() { local ob; ob=$(echo "${1%.*}" | sed 's|[/.]|_|g'); echo "    <ClCompile Include=\"$(w "$1")\"><PreprocessorDefinitions>BITDEPTH=$2;%(PreprocessorDefinitions)</PreprocessorDefinitions><ObjectFileName>\$(IntDir)${ob}_$2.obj</ObjectFileName></ClCompile>"; }
nasm_item()  { # <file> <include dirs relative to project, forward slashes>
  local f=$1; shift; local incs=""; for i in "$@"; do incs="$incs -I&quot;\$(ProjectDir)$(w "$i")/&quot;"; done
  local ob; ob=$(echo "${f%.*}" | sed 's|[/.]|_|g')
  echo "    <CustomBuild Include=\"$(w "$f")\"><Command>nasm -f \$(NasmFormat)$incs -o &quot;\$(IntDir)${ob}_asm.obj&quot; &quot;%(FullPath)&quot;</Command><Outputs>\$(IntDir)${ob}_asm.obj</Outputs><Message>Assembling %(Filename).asm</Message></CustomBuild>"; }

############ bzip2 (sources: bzip2/Makefile, library objects only)
T=$(mktemp); for f in blocksort huffman crctable randtable compress decompress bzlib; do cl_item "bzip2/$f.c"; done > "$T"
emit bzip2 bzip2 bz2 "" "" "" "$T"

############ speex (sources: libspeex/Makefile.am, floating point + smallft)
mkdir -p "$L/speex/include/speex"
cat > "$L/speex/include/speex/speex_config_types.h" <<'H'
/* generated by msvc/regen/gen-libs.sh from speex_config_types.h.in */
#ifndef __SPEEX_TYPES_H__
#define __SPEEX_TYPES_H__
#include <stdint.h>
typedef int16_t spx_int16_t;
typedef uint16_t spx_uint16_t;
typedef int32_t spx_int32_t;
typedef uint32_t spx_uint32_t;
#endif
H
T=$(mktemp); for f in smallft cb_search exc_10_32_table exc_8_128_table filters gain_table hexc_table high_lsp_tables lsp ltp speex stereo vbr vq bits exc_10_16_table exc_20_32_table exc_5_256_table exc_5_64_table gain_table_lbr hexc_10_32_table lpc lsp_tables_nb modes modes_wb nb_celp quant_lsp sb_celp speex_callbacks speex_header window; do cl_item "speex/libspeex/$f.c"; done > "$T"
emit speex speex speex 'speex\win32;speex\include;include' "HAVE_CONFIG_H" "" "$T"

############ opencore-amr (sources: amrnb/Makefile.am with --disable-amrnb-encoder, amrwb/Makefile.am)
O="opencore-amr"; A="$O/opencore/codecs_v2/audio/gsm_amr"
mkdir -p "$L/opencore-amr/include/opencore-amrnb" "$L/opencore-amr/include/opencore-amrwb"
for h in interf_dec; do printf '#include "../../opencore-amr/amrnb/%s.h"\n' $h > "$L/opencore-amr/include/opencore-amrnb/$h.h"; done
for h in dec_if if_rom; do printf '#include "../../opencore-amr/amrwb/%s.h"\n' $h > "$L/opencore-amr/include/opencore-amrwb/$h.h"; done
T=$(mktemp); { cl_item "$O/amrnb/wrapper.cpp"
  for f in agc amrdecode a_refl b_cn_cod bgnscd c_g_aver d1035pf d2_11pf d2_9pf d3_14pf d4_17pf d8_31pf dec_amr dec_gain dec_input_format_tab dec_lag3 dec_lag6 d_gain_c d_gain_p d_plsf_3 d_plsf_5 d_plsf dtx_dec ec_gains ex_ctrl if2_to_ets int_lsf lsp_avg ph_disp post_pro preemph pstfilt qgain475_tab sp_dec wmf_to_ets; do cl_item "$A/amr_nb/dec/src/$f.cpp"; done
  for f in "$L/opencore-amr/$A"/amr_nb/common/src/*.cpp; do b=$(basename "$f"); case $b in bits2prm.cpp|copy.cpp|div_32.cpp|l_abs.cpp|r_fft.cpp|vad1.cpp|vad2.cpp) ;; *) cl_item "$A/amr_nb/common/src/$b";; esac; done; } > "$T"
emit opencore-amr opencore-amrnb opencore-amrnb "$(w $O/oscl);$(w $A/amr_nb/dec/src);$(w $A/amr_nb/common/include);$(w $A/amr_nb/dec/include);$(w $A/common/dec/include);$(w $A/amr_nb/enc/src)" "DISABLE_AMRNB_ENCODER" "" "$T"
T=$(mktemp); { cl_item "$O/amrwb/wrapper.cpp"; for f in agc2_amr_wb band_pass_6k_7k dec_acelp_2p_in_64 dec_acelp_4p_in_64 dec_alg_codebook dec_gain2_amr_wb deemphasis_32 dtx_decoder_amr_wb get_amr_wb_bits highpass_400hz_at_12k8 highpass_50hz_at_12k8 homing_amr_wb_dec interpolate_isp isf_extrapolation isp_az isp_isf lagconceal low_pass_filt_7k median5 mime_io noise_gen_amrwb normalize_amr_wb oversamp_12k8_to_16k phase_dispersion pit_shrp pred_lt4 preemph_amrwb_dec pvamrwbdecoder pvamrwb_math_op q_gain2_tab qisf_ns qisf_ns_tab qpisf_2s qpisf_2s_tab scale_signal synthesis_amr_wb voice_factor wb_syn_filt weight_amrwb_lpc; do cl_item "$A/amr_wb/dec/src/$f.cpp"; done; } > "$T"
emit opencore-amr opencore-amrwb opencore-amrwb "$(w $O/oscl);$(w $A/amr_wb/dec/src);$(w $A/amr_wb/dec/include);$(w $A/common/dec/include)" "" "" "$T"

############ libxml2 (sources: win32/Makefile.msvc XML_OBJS minus nanoftp/nanohttp; options as LAV's gcc build: no ftp/http/python/iconv/zlib)
mkdir -p "$L/libxml2/include/libxml"
{ echo "/* generated by msvc/regen/gen-libs.sh: libxml2's win32config.h is its config.h on MSVC */"; cat "$L/libxml2/libxml2/include/win32config.h"; } > "$L/libxml2/include/config.h"
XV=$(sed -n 's/^m4_define(\[MAJOR_VERSION\], \([0-9]*\)).*/\1/p' "$L/libxml2/libxml2/configure.ac"); XV2=$(sed -n 's/^m4_define(\[MINOR_VERSION\], \([0-9]*\)).*/\1/p' "$L/libxml2/libxml2/configure.ac"); XV3=$(sed -n 's/^m4_define(\[MICRO_VERSION\], \([0-9]*\)).*/\1/p' "$L/libxml2/libxml2/configure.ac")
[ -n "$XV" ] || { echo "cannot read libxml2 version from configure.ac"; exit 1; }
{ echo "/* generated by msvc/regen/gen-libs.sh from xmlversion.h.in for libxml2 $XV.$XV2.$XV3 */"
  sed -e "s/@VERSION@/$XV.$XV2.$XV3/g" -e "s/@LIBXML_VERSION_NUMBER@/$((XV*10000+XV2*100+XV3))/g" -e 's/@LIBXML_VERSION_EXTRA@//g' -e 's/@MODULE_EXTENSION@/.dll/g' \
      -e 's/@WITH_\(TRIO\|THREAD_ALLOC\|FTP\|HTTP\|XPTR_LOCS\|ICONV\|ICU\|MEM_DEBUG\|ZLIB\|LZMA\)@/0/g' -e 's/@WITH_[A-Z0-9_]*@/1/g' "$L/libxml2/libxml2/include/libxml/xmlversion.h.in"; } > "$L/libxml2/include/libxml/xmlversion.h"
grep -q '@' "$L/libxml2/include/libxml/xmlversion.h" && { echo "unreplaced placeholder in xmlversion.h"; exit 1; }
T=$(mktemp); for f in buf c14n catalog chvalid debugXML dict encoding entities error globals hash HTMLparser HTMLtree legacy list parser parserInternals pattern relaxng SAX2 SAX schematron threads tree uri valid xinclude xlink xmlIO xmlmemory xmlreader xmlregexp xmlmodule xmlsave xmlschemas xmlschemastypes xmlunicode xmlwriter xpath xpointer xmlstring; do cl_item "libxml2/$f.c"; done > "$T"
emit libxml2 libxml2 xml2 'include;libxml2\include;libxml2' "LIBXML_STATIC;NOLIBTOOL;HAVE_WIN32_THREADS;_REENTRANT" "/wd4244 /wd4267" "$T"

############ dav1d (sources: src/meson.build for x86 with 8+16 bit depths; config from meson.build cdata)
DV=$(sed -n "s/^ *version: '\([0-9.]*\)'.*/\1/p" "$L/dav1d/dav1d/meson.build" | head -1)
[ -n "$DV" ] || { echo "cannot read dav1d version from meson.build"; exit 1; }
mkdir -p "$L/dav1d/include"
printf '/* generated by msvc/regen/gen-libs.sh */\n#define DAV1D_VERSION "%s"\n' "$DV" > "$L/dav1d/include/vcs_version.h"
cat > "$L/dav1d/include/config.h" <<'H'
/* generated by msvc/regen/gen-libs.sh: dav1d config.h for MSVC x86/x64 (what meson would write) */
#pragma once
#if defined(_M_X64)
#define ARCH_X86_64 1
#define ARCH_X86_32 0
#else
#define ARCH_X86_64 0
#define ARCH_X86_32 1
#endif
#define ARCH_X86 1
#define ARCH_AARCH64 0
#define ARCH_ARM 0
#define ARCH_PPC64LE 0
#define ARCH_RISCV 0
#define ARCH_RV32 0
#define ARCH_RV64 0
#define ARCH_LOONGARCH 0
#define ARCH_LOONGARCH32 0
#define ARCH_LOONGARCH64 0
#define CONFIG_16BPC 1
#define CONFIG_8BPC 1
#define CONFIG_LOG 1
#define CONFIG_MACOS_KPERF 0
#define ENDIANNESS_BIG 0
#define HAVE_ALIGNED_ALLOC 0
#define HAVE_ASM 1
#define HAVE_AS_FUNC 0
#define HAVE_AS_ARCH_DIRECTIVE 0
#define HAVE_C11_GENERIC 0
#define HAVE_CLOCK_GETTIME 0
#define HAVE_DLSYM 0
#define HAVE_ELF_AUX_INFO 0
#define HAVE_GETAUXVAL 0
#define HAVE_IO_H 1
#define HAVE_MEMALIGN 0
#define HAVE_POSIX_MEMALIGN 0
#define HAVE_PTHREAD_GETAFFINITY_NP 0
#define HAVE_PTHREAD_NP_H 0
#define HAVE_PTHREAD_SETAFFINITY_NP 0
#define HAVE_PTHREAD_SETNAME_NP 0
#define HAVE_PTHREAD_SET_NAME_NP 0
#define HAVE_SYS_TYPES_H 1
#define HAVE_UNISTD_H 0
#define STACK_ALIGNMENT 16
#define TRIM_DSP_FUNCTIONS 0
#define UNICODE 1
#define _UNICODE 1
#define _CRT_DECLARE_NONSTDC_NAMES 1
#define _FILE_OFFSET_BITS 64
#define _WIN32_WINNT 0x0601
#define fseeko _fseeki64
#define ftello _ftelli64
H
cat > "$L/dav1d/include/config.asm" <<'H'
; generated by msvc/regen/gen-libs.sh: dav1d config.asm for nasm (what meson would write)
%ifidn __OUTPUT_FORMAT__,win64
%define ARCH_X86_32 0
%define ARCH_X86_64 1
%else
%define ARCH_X86_32 1
%define ARCH_X86_64 0
%define PREFIX 1
%endif
%define FORCE_VEX_ENCODING 0
%define PIC 1
%define STACK_ALIGNMENT 16
%define private_prefix dav1d
H
T=$(mktemp); {
  for f in cdf cpu ctx data decode dequant_tables getbits intra_edge itx_1d lf_mask lib log mem msac obu pal picture qm ref refmvs scan tables thread_task warpmv wedge x86/cpu win32/thread; do cl_item "dav1d/src/$f.c"; done
  for f in cdef_apply_tmpl cdef_tmpl fg_apply_tmpl filmgrain_tmpl ipred_prepare_tmpl ipred_tmpl itx_tmpl lf_apply_tmpl loopfilter_tmpl looprestoration_tmpl lr_apply_tmpl mc_tmpl recon_tmpl; do cl_item_bd "dav1d/src/$f.c" 8; cl_item_bd "dav1d/src/$f.c" 16; done
  for f in cpuid msac pal refmvs itx_avx512 cdef_avx2 itx_avx2 cdef_sse itx_sse cdef_avx512 filmgrain_avx512 ipred_avx512 loopfilter_avx512 looprestoration_avx512 mc_avx512 filmgrain_avx2 ipred_avx2 loopfilter_avx2 looprestoration_avx2 mc_avx2 filmgrain_sse ipred_sse loopfilter_sse looprestoration_sse mc_sse cdef16_avx512 filmgrain16_avx512 ipred16_avx512 itx16_avx512 loopfilter16_avx512 looprestoration16_avx512 mc16_avx512 cdef16_avx2 filmgrain16_avx2 ipred16_avx2 itx16_avx2 loopfilter16_avx2 looprestoration16_avx2 mc16_avx2 cdef16_sse filmgrain16_sse ipred16_sse itx16_sse loopfilter16_sse looprestoration16_sse mc16_sse; do nasm_item "dav1d/src/x86/$f.asm" dav1d/src include; done
} > "$T"
emit dav1d dav1d dav1d 'include;dav1d\include\compat\msvc;dav1d;dav1d\include;dav1d\src' "" "/wd4028 /wd4090 /wd4996" "$T"
echo "done"
